import org.junit.jupiter.api.Test;

class BlankNodeGraphSelectionTest {
	private static final ValueFactory VF = SimpleValueFactory.getInstance();

	@Test
	void namedDatasetSelectsExactBlankNodeGraph() {
		Resource graph = VF.createBNode("graph");
		Resource hidden = VF.createBNode("hidden");
		var dataset = new SimpleDataset();
		dataset.addNamedGraph(graph);
		Statement statement = VF.createStatement(VF.createBNode("subject"), VF.createIRI("urn:p"),
				VF.createLiteral("value"), graph);
		TripleSource source = new TripleSource() {
			public ValueFactory getValueFactory() {
				return VF;
			}

			public CloseableIteration<? extends Statement> getStatements(Resource s, IRI p, Value o,
					Resource... contexts) {
				boolean accepted = contexts.length == 0 || Arrays.asList(contexts).contains(graph);
				return new CloseableIteratorIteration<>(accepted ? List.of(statement).iterator()
						: List.<Statement>of().iterator());
			}
		};
		var strategy = new DefaultEvaluationStrategy(source, dataset, null);
		var pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g", graph));
		try (var rows = strategy.precompile(pattern).evaluate(EmptyBindingSet.getInstance())) {
			assertTrue(rows.hasNext());
			assertEquals(statement.getSubject(), rows.next().getValue("s"));
			assertFalse(rows.hasNext());
		}
		pattern = new StatementPattern(StatementPattern.Scope.NAMED_CONTEXTS,
				Var.of("s"), Var.of("p"), Var.of("o"), Var.of("g", hidden));
		try (var rows = strategy.precompile(pattern).evaluate(EmptyBindingSet.getInstance())) {
			assertFalse(rows.hasNext(), "a reference must not bypass effective dataset restrictions");
		}
	}
}
